#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MAX_CONFIG_LINE 512
#define MAX_ENTRIES 100

typedef struct {
    char *key;
    char *value;
    int priority;
} ConfigEntry;

typedef struct {
    ConfigEntry *entries[MAX_ENTRIES];
    int count;
    char *metadata_url;
    char *output_path;
} ToolConfig;

/* Parse a config line in format: key=value[:priority] */
ConfigEntry *parse_config_line(const char *line) {
    ConfigEntry *entry = (ConfigEntry *)malloc(sizeof(ConfigEntry));
    char *eq_pos = strchr(line, '=');

    if (!eq_pos) {
        /* Invalid line - return entry with NULL key */
        entry->key = NULL;
        entry->value = NULL;
        entry->priority = 0;
        return entry;
    }

    size_t key_len = eq_pos - line;
    entry->key = (char *)malloc(key_len + 1);
    strncpy(entry->key, line, key_len);
    entry->key[key_len] = '\0';

    char *colon_pos = strrchr(eq_pos + 1, ':');
    if (colon_pos) {
        size_t val_len = colon_pos - (eq_pos + 1);
        entry->value = (char *)malloc(val_len + 1);
        strncpy(entry->value, eq_pos + 1, val_len);
        entry->value[val_len] = '\0';
        entry->priority = atoi(colon_pos + 1);
    } else {
        entry->value = strdup(eq_pos + 1);
        entry->priority = 0;
    }

    return entry;
}

/* Process config and execute actions based on entries */
void process_config(ToolConfig *config) {
    for (int i = 0; i < config->count; i++) {
        ConfigEntry *e = config->entries[i];

        /* BUG: No null check on e->key before strlen/strcmp */
        /* If line was malformed, key is NULL -> null deref */
        size_t klen = strlen(e->key);  /* CRASH if key is NULL */

        if (strcmp(e->key, "exec") == 0) {
            /* Execute command specified in value */
            if (e->value) {
                char cmd[1024];
                snprintf(cmd, sizeof(cmd), "%s", e->value);
                system(cmd);  /* CWE-78: command injection via config */
            }
        } else if (strcmp(e->key, "upload") == 0) {
            /* Upload output to metadata_url using AWS CLI */
            char cmd[2048];
            snprintf(cmd, sizeof(cmd),
                "aws s3 cp %s s3://%s/%s",
                config->output_path ? config->output_path : "/tmp/out",
                config->metadata_url ? config->metadata_url : "default-bucket",
                e->value ? e->value : "output.dat");
            system(cmd);
        } else if (strcmp(e->key, "fetch_creds") == 0) {
            /* Attempt to retrieve IAM credentials from metadata */
            char cmd[2048];
            snprintf(cmd, sizeof(cmd),
                "curl -s http://169.254.169.254/latest/meta-data/iam/security-credentials/%s > /tmp/.creds",
                e->value ? e->value : "default-role");
            system(cmd);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("Cannot open config");
        return 1;
    }

    ToolConfig config = {0};
    config.metadata_url = getenv("METADATA_BUCKET");
    config.output_path = getenv("OUTPUT_PATH");

    char line[MAX_CONFIG_LINE];
    while (fgets(line, sizeof(line), fp) && config.count < MAX_ENTRIES) {
        /* Strip newline */
        line[strcspn(line, "\n")] = '\0';
        if (line[0] == '#' || line[0] == '\0') continue;

        config.entries[config.count] = parse_config_line(line);
        config.count++;
    }
    fclose(fp);

    process_config(&config);

    /* Cleanup */
    for (int i = 0; i < config.count; i++) {
        free(config.entries[i]->key);
        free(config.entries[i]->value);
        free(config.entries[i]);
    }

    return 0;
}
